using System.Text;
namespace BellasBoutique.Web.Services;
// PDF sencillo, sin dependencias adicionales. Texto WinAnsi y páginas de 38 líneas.
public static class PdfReporte{
 public static byte[] Crear(string titulo,List<string> lineas){var enc=Encoding.Latin1;var inv=System.Globalization.CultureInfo.InvariantCulture;string Esc(string s)=>s.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)").Replace("\r"," ").Replace("\n"," ");var pages=lineas.Chunk(38).ToArray();var objects=new List<string>{"<< /Type /Catalog /Pages 2 0 R >>","", "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"};var kids=new List<string>();foreach(var page in pages){int n=objects.Count+1;kids.Add($"{n} 0 R");var content=new StringBuilder("0.98 0.91 0.94 rg 0 710 595 132 re f\n0.17 0.12 0.16 rg\n");void Text(string s,int x,int y,int size)=>content.Append($"BT /F1 {size} Tf {x} {y} Td ({Esc(s)}) Tj ET\n");Text("BellasBoutique",40,790,26);Text(titulo,40,750,18);int y=680;foreach(var l in page){Text(l.Length>100?l[..100]:l,40,y,11);y-=16;}Text("BellasBoutique | Proyecto académico IHC",40,35,9);var st=content.ToString();objects.Add($"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R >> >> /Contents {n+1} 0 R >>");objects.Add($"<< /Length {enc.GetByteCount(st)} >>\nstream\n{st}endstream");}objects[1]=$"<< /Type /Pages /Kids [{string.Join(" ",kids)}] /Count {pages.Length} >>";using var ms=new MemoryStream();void W(string s)=>ms.Write(enc.GetBytes(s));W("%PDF-1.4\n");var pos=new List<long>{0};for(int i=0;i<objects.Count;i++){pos.Add(ms.Position);W($"{i+1} 0 obj\n{objects[i]}\nendobj\n");}long xref=ms.Position;W($"xref\n0 {pos.Count}\n0000000000 65535 f \n");foreach(var p in pos.Skip(1))W(p.ToString("D10",inv)+" 00000 n \n");W($"trailer\n<< /Size {pos.Count} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n");return ms.ToArray();}
}